// LoadCountRoles loads the count of Roles into the C struct
func (o *Permission) LoadCountRoles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Roles(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Roles = &count
	return nil
}

// LoadCountRoles loads the count of Roles for a slice in a single batch query
func (os PermissionSlice) LoadCountRoles(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			RolePermissions.Columns.PermissionID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Multi-hop: FROM first join table, JOIN through to final related table
		sm.From(RolePermissions.NameAsExpr()),
		sm.InnerJoin(Roles.NameAsExpr()).On(
			Roles.Columns.ID.EQ(RolePermissions.Columns.RoleID),
		),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(RolePermissions.Columns.PermissionID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(RolePermissions.Columns.PermissionID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Roles = &count
	}

	return nil
}

type permissionJoins[Q dialect.Joinable] struct {
	typ   string
	Roles modAs[Q, roleColumns]
}

func (j permissionJoins[Q]) aliasedAs(alias string) permissionJoins[Q] {
	return buildPermissionJoins[Q](buildPermissionColumns(alias), j.typ)
}

func buildPermissionJoins[Q dialect.Joinable](cols permissionColumns, typ string) permissionJoins[Q] {
	return permissionJoins[Q]{
		typ: typ,
		Roles: modAs[Q, roleColumns]{
			c: Roles.Columns,
			f: func(to roleColumns) bob.Mod[Q] {
				random := strconv.FormatInt(randInt(), 10)
				mods := make(mods.QueryMods[Q], 0, 2)

				{
					to := RolePermissions.Columns.AliasedAs(RolePermissions.Columns.Alias() + random)
					mods = append(mods, dialect.Join[Q](typ, RolePermissions.NameExpr().As(to.Alias())).On(
						to.PermissionID.EQ(cols.ID),
					))
				}
				{
					cols := RolePermissions.Columns.AliasedAs(RolePermissions.Columns.Alias() + random)
					mods = append(mods, dialect.Join[Q](typ, Roles.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RoleID),
					))
				}

				return mods
			},
		},
	}
}
